style.css:
@-moz-document domain("arkhamdb.com") {
body {
    font-family: "Open Sans", "Helvetica Neue", Helvetica, Arial, sans-serif;
    color: #9a9a9a;
    background-color: #1A1A1A;
  }

  .modal-content {
    color: #2B80C5;
    background-color: #1A1A1A;
  }

  .container.main.white {
    background-color: unset;
  }

  a {
    color: #2B80C5;
    text-decoration: none
  }
  .btn-link {
    color: #FAFAFA;
    font-weight: normal;
    border-radius: 0;
  }
  .table-striped > tbody > tr:nth-of-type(even) {
    background-color: #333333;
  }
  .table-striped > tbody > tr:nth-of-type(odd) {
    background-color: #333333;
  }
  .spoiler {
    background-color: #606060;
    color: #606060 !important;
  }
  .qtip-bootstrap {
    font-size: 14px;
    line-height: 20px;
    color: #FAFAFA;
    padding: 1px;
    background-color: #333333;
    border: 1px solid #ccc;
    border: 1px solid rgba(0, 0, 0, 0.2);
  }
  .bg-guardian {
    background-color: #052D4D !important;
    color: white !important;
  }
  .border-guardian {
    border-color: #052D4D !important;
  }
  .panel-body {
    background-color: #232323;
    padding: 15px;
  }
  .card-content {
    color: #F0F0F0;
  }
  .form-control {
    background-color: #232323;
    color: #9a9a9a;
    padding: 4px 4px;
  }
  .twitter-typeahead {
    background-color: #232323;
  }
  footer {
    background-color: #152526;
  }

  .builder-tabs li.active a {
    background-color: #666666
  }

  .btn.active {
    color: #F0F0F0 !important;
    background-color: #666666 !important;
    border-color: #999999 !important;
  }

  .btn-default {
    color: #F0F0F0 !important;
    background-color: #232323 !important;
    background-image: linear-gradient(#232323, #232323, #232323);
  }

  button.close {
    color: #F0F0F0 !important;
  }

  .tt-dropdown-menu {
    background-color: #232323 !important;
  }

  /* Pagination */
  .pagination > li > a,
  .pagination > li > span {
    color: #F0F0F0;
    background-color: #232323;
  }

  .pagination-sm > li:first-child > a,
  .pagination-sm > li:first-child > span {
    color: #F0F0F0;
    background-color: #232323;
  }

  /* Graph colors */
  .highcharts-background {
    fill: #333333;
  }
  text.highcharts-title,
  text.highcharts-subtitle {
    color: #BEBEBE !important;
    fill: #BEBEBE !important;
  }

  .highcharts-axis-labels > span,
  .highcharts-axis-labels > text {
    color: #BEBEBE !important;
    fill: #BEBEBE !important;
  }


  /* Various text colors */
  a:hover,
  a:focus {
    color: #757486;
  }

  .social-icon-version {
    color: #5e5ef7;
  }

  .text-muted {
    color: #ADADAD;
  }

  /* Classes */
  .fg-neutral {
    color: #C0C0C0 !important;
  }

  .fg-mystic {
    color: #6B5EBB !important;
  }

  .bg-guardian {
    background-color: #2b80c5 !important;
    color: white !important
  }

  .bg-survivor {
    background-color: #cc3038 !important;
    color: white !important
  }

  .bg-seeker {
    background-color: #ff8f3f !important
  }

  .bg-rogue {
    background-color: #107116 !important;
    color: white !important
  }

  /* Skill symbols */
  .color-will,
  .color-willpower {
    color: #0071C0
  }

  .color-lore,
  .color-intellect {
    color: #B13A9C
  }

  .color-strength,
  .color-combat {
    color: #A2300F
  }

  .color-agility {
    color: #107116
  }

  .color-wild {
    color: #A08233
  }

  /* Main screen deck tiles */
  .row > div > div:not(.bg-faction)  {
    background-color: unset !important
  }

  .row > div > div:not(.bg-faction) > div {
    background-color: rgba(26, 26, 26, 0.88) !important
  }
}
